commands.command:
/bin/zsh -lc "set -o pipefail
{
  echo '# candidate provenance'
  date -u '+utc=%Y-%m-%dT%H:%M:%SZ'
  echo 'branch='"'$(git branch --show-current)
  echo '"'head='"'$(git rev-parse HEAD)
  echo '"'origin_main='"'$(git rev-parse origin/main)
  echo '"'status:'
  git status --short --branch
  echo 'version:'
  ./bin/agent-center version
} | tee docs/acceptance/insight-test-instance-20260831/raw/00-provenance.log
{
  echo '# make lint'
  make lint
} > docs/acceptance/insight-test-instance-20260831/raw/01-make-lint.log 2>&1; echo make_lint_exit="'$? | tee -a docs/acceptance/insight-test-instance-20260831/raw/01-make-lint.log
{
  echo '"'# make build'
  make build
} > docs/acceptance/insight-test-instance-20260831/raw/02-make-build.log 2>&1; echo make_build_exit="'$? | tee -a docs/acceptance/insight-test-instance-20260831/raw/02-make-build.log'
